{+    d_{A,j}(W)\le24s^2+3\Delta_j+3d_{B,j}(W).+}
{+  \]+}
{+  No value or agreement bound is assumed.+}
{+\end{theorem}+}
{+\begin{proof}+}
{+  \leanok+}
{+  \uses{thm:ms-ideal-measurement-transfer}+}
