{+\end{proof}+}

{+\begin{theorem}[Formalization support: completed constraint transfer]+}
{+  \label{thm:ms-constraint-distance-transfer}+}
{+  \lean{MIPStarRE.QPBT.ms_constraint_distance_A_le}+}
{+  \leanok+}
{+  \uses{def:ms-prescribed-distances, def:tensor-product-value}+}
