{+\begin{theorem}[Formalization support: completed extraction with agreement error]+}
{+  \label{thm:ms-completed-extraction-agreement}+}
{+  \lean{MIPStarRE.QPBT.exists_ms_one_way_rigidity_with_agreement}+}
{+  \leanok+}
