{+    s_w\le155904\sqrt\eps,\qquad+}
{+    d_{B,j}\le2\cdot10^{12}\eps,\qquad+}
{+    d_{A,j}\le7\cdot10^{12}\eps+3\Delta_j\quad(j=1,5).+}
