{+\begin{theorem}[Formalization support: removing completion from effects]+}
{+  \label{thm:ms-prescribed-effect-transfer}+}
{+  \lean{MIPStarRE.QPBT.ms_prescribed_operator_distance_A_le}+}
{+  \lean{MIPStarRE.QPBT.ms_prescribed_operator_distance_B_le}+}
{+  \leanok+}
{+  \uses{def:ms-prescribed-distances, def:tensor-product-value}+}
{+  Let $\eps,s\in\mathbb R$, let the strategy have value at least+}
{+  $1-\eps$, and let $w$ be any extraction witness with $s_w\le s$.+}
{+  For every cell $j$ and Pauli kind $W$,+}
{+  \begin{align*}+}
{+    d^{\mathrm{pre}}_{A,j}(W)&\le2d_{A,j}(W)+144\eps+4s^2,\\+}
{+    d^{\mathrm{pre}}_{B,j}(W)&\le2d_{B,j}(W)+144\eps+4s^2.+}
