{+\begin{theorem}[Formalization support: prescribed measurement extraction]+}
{+  \label{thm:ms-prescribed-measurement-extraction}+}
{+  \lean{MIPStarRE.QPBT.exists_ms_prescribed_measurements_with_agreement}+}
