{+\begin{theorem}[Formalization support: products through a commuting contraction]+}
{+  \label{thm:ms-product-opposite-transfer}+}
{+  \lean{MIPStarRE.QPBT.MagicSquareRigidity.norm_product_via_opposite_le}+}
{+  \leanok+}
{+  Let $R,Z,D$ be operators on a finite-dimensional complex Hilbert space,+}
{+  $\psi$ any vector, and $a,r\in\mathbb R$. Suppose+}
{+  $R^\dagger R,D^\dagger D\le I$, $RD=DR$,+}
{+  $\|(Z-D)\psi\|\le a$, and $\|R\psi\|\le r$. Then+}
{+  $\|RZ\psi\|\le a+r$. No contractivity assumption on $Z$ is needed.+}
{+\end{theorem}+}
{+\begin{proof}+}
{+  \leanok+}
{+  Write $RZ=R(Z-D)+DR$ and use contractivity in the triangle inequality.+}
{+\end{proof}+}

{+\begin{theorem}[Formalization support: subtracting errors from an anticommutator]+}
{+  \label{thm:ms-anticommutator-subtraction}+}
{+  \lean{MIPStarRE.QPBT.MagicSquareRigidity.norm_anticommutator_sub_errors_le}+}
{+  \lean{MIPStarRE.QPBT.MagicSquareRigidity.norm_anticommutator_sub_apply_le}+}
{+  \leanok+}
{+  Let $X,Z,R,T,C,D$ be contractions on a finite-dimensional complex+}
{+  Hilbert space, let $\psi$ be any vector, and let $a,r\in\mathbb R$.+}
{+  Assume $RD=DR$, $TC=CT$, and+}
{+  \[+}
{+    \|(X-C)\psi\|,\|(Z-D)\psi\|\le a,\qquad+}
{+    \|R\psi\|,\|T\psi\|\le r.+}
{+  \]+}
{+  Then+}
{+  \[+}
{+    \|((X-R)(Z-T)+(Z-T)(X-R))\psi\|+}
{+      \le\|(XZ+ZX)\psi\|+2a+6r.+}
{+  \]+}
{+  Independently, for any four contractions $X,Z,R,T$ and any vector $v$,+}
{+  \[+}
{+    \|((X-R)(Z-T)+(Z-T)(X-R))v\|\le8\|v\|.+}
{+  \]+}
{+  The latter bound requires none of the comparison or commutation hypotheses.+}
{+\end{theorem}+}
{+\begin{proof}+}
{+  \leanok+}
{+  \uses{thm:ms-product-opposite-transfer}+}
{+  The difference from $XZ+ZX$ is the negative of+}
{+  $RZ+(X-R)T+TX+(Z-T)R$. The product-transfer estimate bounds the first+}
{+  and third terms by $a+r$ each; the other two are bounded by $2r$ each.+}
{+  For the independent estimate, each difference of contractions has norm+}
{+  at most two, so each product has norm at most four.+}
{+\end{proof}+}

{+\begin{theorem}[Formalization support: prescribed anticommutators on the original state]+}
{+  \label{thm:ms-prescribed-original-anticommutators}+}
{+  \lean{MIPStarRE.QPBT.MagicSquareRigidity.ms_prescribed_anticommutator_norm_A}+}
{+  \lean{MIPStarRE.QPBT.MagicSquareRigidity.ms_prescribed_anticommutator_norm_B}+}
{+  \leanok+}
{+  \uses{def:ms-prescribed-distances, def:tensor-product-value}+}
{+  Let $\eps\ge0$ and let the strategy have value at least $1-\eps$.+}
{+  Its original prescribed observables satisfy+}
{+  \begin{align*}+}
{+    \|((O_{A,1}O_{A,5}+O_{A,5}O_{A,1})\ot I)\psi\|&\le1148\sqrt\eps,\\+}
{+    \|(I\ot(O_{B,1}O_{B,5}+O_{B,5}O_{B,1}))\psi\|&\le1148\sqrt\eps.+}
{+  \end{align*}+}
{+  Neither assertion requires an extraction witness or variable agreement.+}
{+\end{theorem}+}
{+\begin{proof}+}
{+  \leanok+}
{+  \uses{thm:ms-completion-identities, thm:ms-wrong-form-bounds,+}
{+    thm:ms-original-incidence-estimates, thm:ms-anticommutator-subtraction,+}
{+    lem:qld-ms-anticommutator-original-state}+}
{+  Use the completed variable observables as $X,Z$ and their wrong-form+}
{+  effects as $R,T$. Opposite-player constraint observables at $(1,1)$+}
{+  and $(2,2)$ supply $C,D$ with error $a=12\sqrt\eps$ and commute+}
{+  with the local wrong-form effects. Their action has bound+}
{+  $r=6\sqrt\eps$. Subtraction therefore costs $60\sqrt\eps$.+}
{+  The completed anticommutator has squared norm at most $1183680\eps$,+}
{+  hence norm at most $1088\sqrt\eps$, on either player's factor.+}
{+\end{proof}+}

{+\begin{theorem}[Formalization support: prescribed anticommutators on the ideal state]+}
{+  \label{thm:ms-prescribed-ideal-anticommutators}+}
{+  \lean{MIPStarRE.QPBT.ms_prescribed_anticommutator_distance_A_le}+}
{+  \lean{MIPStarRE.QPBT.ms_prescribed_anticommutator_distance_B_le}+}
{+  \leanok+}
{+  \uses{def:ms-prescribed-distances, def:tensor-product-value}+}
{+  Let $\eps\ge0$, let the strategy have value at least $1-\eps$, and+}
{+  let any extraction witness $w$ and real $s$ satisfy $s_w\le s$. Then+}
{+  \[+}
{+    a^{\mathrm{pre}}_A\le(1148\sqrt\eps+8s)^2,\qquad+}
{+    a^{\mathrm{pre}}_B\le(1148\sqrt\eps+8s)^2.+}
{+  \]+}
{+\end{theorem}+}
{+\begin{proof}+}
{+  \leanok+}
{+  \uses{thm:ms-prescribed-original-anticommutators, thm:ms-anticommutator-subtraction,+}
{+    thm:ms-completion-identities}+}
{+  Conjugation by an isometry preserves products and the norm on the+}
{+  embedded original state. The transported prescribed anticommutator is+}
{+  an anticommutator of two differences of contractions, so its action+}
{+  on the state difference has norm at most $8s$. Add the original+}
{+  $1148\sqrt\eps$ bound and square.+}
{+\end{proof}+}

